struct ScrollState131 {
 uintptr_t owner=0;float saved=0,written=0;bool active=false;
 void Reset(){*this={};}
 template<class Read,class Set> bool Apply(uintptr_t camera,int percent,bool enabled,Read read,Set set){
  if(!camera){Reset();return true;}if(percent<0||percent>700)return false;if(camera!=owner)Reset();
  float current=0;if(!read(camera,current)||!std::isfinite(current)||current<0||current>10000){Reset();return false;}
  if(enabled){if(!active||current!=written)saved=current;owner=camera;const float value=percent?percent/100.f:1.f;
   if(current!=value&&!set(camera,value)){Reset();return false;}float observed=0;if(!read(camera,observed)||observed!=value){Reset();return false;}written=observed;active=true;
  }else if(active){if(current==written&&current!=saved&&!set(camera,saved))return false;Reset();}return true;
 }
};
inline bool ReadScroll131(uintptr_t camera,unsigned field,float& value){__try{value=*reinterpret_cast<float*>(camera+field);return std::isfinite(value)&&value>=0&&value<=10000;}__except(1){return false;}}
inline bool SetScroll131(uintptr_t camera,uintptr_t entry,float value){__try{reinterpret_cast<ScrollSetter131>(entry)(camera,value);return true;}__except(1){return false;}}
struct ScrollPair131 {
 std::array<ScrollState131,2> values{};
 void Reset(){for(auto& value:values)value.Reset();}
 bool Update(uintptr_t base,unsigned build,uintptr_t camera,bool enabled,const Config& config){
  const auto* p=ScrollProfileFor131(build);if(!p||!ScrollCode131(base,build)||!ComponentIdentity131(camera,base+p->cameraTable)){Reset();return false;}
  bool ok=true;const int percent[]={config.keyboardScroll,config.mouseScroll};
  for(unsigned i=0;i<2;++i)ok=values[i].Apply(camera,percent[i],enabled,[&](uintptr_t object,float& value){return ComponentIdentity131(object,base+p->cameraTable)&&ReadScroll131(object,p->field[i],value);},[&](uintptr_t object,float value){return ComponentIdentity131(object,base+p->cameraTable)&&SetScroll131(object,base+p->setter[i],value);})&&ok;
  return ok;
 }
};
inline bool ParseScrollPercent131(const std::wstring& args,int& value){if(args.find_first_of(L"\r\n")!=std::wstring::npos||args.find(L'\0')!=std::wstring::npos)return false;std::wistringstream in(args);int parsed=0;std::wstring extra;if(!(in>>parsed)||in>>extra||parsed<0||parsed>700)return false;value=parsed;return true;}
template<class Save,class Reload> bool ApplyScrollCommand131(const std::wstring& name,const std::wstring& args,Save save,Reload reload){
 if(name!=L"#kscroll"&&name!=L"#mscroll")return false;int value=0;if(!ParseScrollPercent131(args,value))return false;
 if(!save(L"Event",name==L"#kscroll"?L"Keyboard Scroll Speed":L"Mouse Scroll Speed",std::to_wstring(value)))return false;reload();return true;
}
